const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kabul = ee.Geometry.Point([69.2075, 34.5553]);
  const radius = 30 * 1609.34; // 30 miles to meters
  const aoi = kabul.buffer(radius);

  // 2. Data Acquisition
  const fldas = ee.ImageCollection('NASA/FLDAS/NOAH01/C/GL/M/V001');

  // February 2017
  const col2017 = fldas
    .filterDate('2017-02-01', '2017-03-01')
    .filterBounds(aoi)
    .select('SWE_inst');

  // February 2018
  const col2018 = fldas
    .filterDate('2018-02-01', '2018-03-01')
    .filterBounds(aoi)
    .select('SWE_inst');

  const size2017 = await col2017.size().getInfo();
  const size2018 = await col2018.size().getInfo();

  console.log(`2017 Images: ${size2017}`);
  console.log(`2018 Images: ${size2018}`);

  if (size2017 === 0 || size2018 === 0) {
    console.log("Missing data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get mean SWE for each period
  const swe2017 = col2017.mean();
  const swe2018 = col2018.mean();

  // Calculate statistics
  const stats2017 = await swe2017.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const stats2018 = await swe2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const mean2017 = stats2017['SWE_inst_mean'];
  const count2017 = stats2017['SWE_inst_count'];
  const mean2018 = stats2018['SWE_inst_mean'];
  const count2018 = stats2018['SWE_inst_count'];

  console.log(`2017 SWE: ${mean2017} kg/m² (Pixels: ${count2017})`);
  console.log(`2018 SWE: ${mean2018} kg/m² (Pixels: ${count2018})`);

  // 4. Validation
  if (count2017 === 0 || count2018 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean2017 === null || mean2017 === undefined || 
      mean2018 === null || mean2018 === undefined ||
      isNaN(mean2017) || isNaN(mean2018)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Final Answer
  if (mean2018 > mean2017) {
    console.log("February 2018 had more SWE than February 2017.");
    console.log("<answer>A</answer>");
  } else {
    console.log("February 2018 did not have more SWE than February 2017.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
